from hermes_tools import terminal
cmd = r'''python3 - <<'PY'
import sqlite3,re,json,collections
p='/home/USER/continual-arc-baselines/.workbench/stage1/HA-hermes-luna6-medium-fresh0/frozen/held-out-reference/play/users/u027/system/state/hermes/state.db'
c=sqlite3.connect('file:'+p+'?mode=ro',uri=True)
sid='003c6c55-705c-4ba2-abe1-ca22cb716e30'
first=c.execute("select content from messages where session_id=? and role='user' order by id limit 1",(sid,)).fetchone()[0]
block=first.split('Test input (23x25):\n',1)[1].split('\nWrong attempts used:',1)[0]
g=[[int(x) for x in ln.split()] for ln in block.splitlines()]
R,C=len(g),len(g[0]); assert (R,C)==(23,25) and all(len(x)==C for x in g)
axes_r={4,11}; axes_c={5}
seen=set(); comps=[]
for r in range(R):
 for col in range(C):
  if g[r][col]!=2 or (r,col) in seen: continue
  q=[(r,col)]; seen.add((r,col)); cells=[]
  while q:
   a,b=q.pop(); cells.append((a,b))
   for x,y in ((a-1,b),(a+1,b),(a,b-1),(a,b+1)):
    if 0<=x<R and 0<=y<C and g[x][y]==2 and (x,y) not in seen:
     seen.add((x,y)); q.append((x,y))
  hit=any(a in axes_r or b in axes_c for a,b in cells)
  comps.append((hit, min(a for a,b in cells),max(a for a,b in cells),min(b for a,b in cells),max(b for a,b in cells),len(cells),cells))
out=[row[:] for row in g]
for hit,*_,cells in comps:
 if hit:
  for a,b in cells: out[a][b]=1
for r in range(R):
 for col in range(C):
  if r in axes_r or col in axes_c: out[r][col]=1
print('components:')
for hit,r0,r1,c0,c1,n,cells in comps: print('FILL' if hit else 'keep',f'r{r0}-{r1} c{c0}-{c1} n={n}')
print('candidate grid:')
print(json.dumps(out,separators=(',',':')))
print('rows:')
for row in out: print(' '.join(map(str,row)))
print('previous submit audits:')
for mid,content in c.execute("select id,content from messages where session_id=? and role='assistant' and content like '%\"action\":\"submit\"%' order by id",(sid,)):
 ans=json.loads(content); cand=ans['grid']; diffs=[(r,col,g[r][col],out[r][col],cand[r][col]) for r in range(R) for col in range(C) if cand[r][col]!=out[r][col]]
 print(mid,'shape',len(cand),len(cand[0]),'diff_count',len(diffs),'first_diffs',diffs[:25])
PY'''
r=terminal(cmd,timeout=30,workdir='/home/USER/continual-arc-baselines/.workbench/stage1/HA-hermes-luna6-medium-fresh0/frozen/held-out-reference/play/users/u027/system/state/home')
print(r['output'])

